CREATE POLICY "client logos public read" ON storage.objects FOR SELECT USING (bucket_id = 'client-logos');
CREATE POLICY "client logos owner insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'client-logos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "client logos owner update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'client-logos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "client logos owner delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'client-logos' AND (storage.foldername(name))[1] = auth.uid()::text);